//! The tray PNGs (`icons/tray/*@2x.png`, generated by `scripts/gen-icons.sh`) are decoded at
//! compile time by `include_image!` in `src/tray.rs`, so a corrupt file already fails the build.
//! This only checks what the build does not: each file is a square RGBA PNG of 44 px.

use std::path::Path;

const NAMES: [&str; 5] = [
    "idle-template",
    "idle-color",
    "recording",
    "paused-template",
    "paused-color",
];

/// Width, height and colour type from the PNG header.
fn png_header(path: &Path) -> (u32, u32, u8) {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    assert_eq!(
        &bytes[..8],
        b"\x89PNG\r\n\x1a\n",
        "{} is not a PNG",
        path.display()
    );
    let be = |at: usize| u32::from_be_bytes(bytes[at..at + 4].try_into().expect("4 bytes"));
    (be(16), be(20), bytes[25])
}

#[test]
fn tray_icons_are_square_rgba_pngs() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("icons/tray");
    for name in NAMES {
        let path = dir.join(format!("{name}@2x.png"));
        // Colour type 6 is RGBA.
        assert_eq!(png_header(&path), (44, 44, 6), "{}", path.display());
    }
}
